svn co --no-auth-cache --username $3 --password $4 http://svn.ynov-bordeaux.com/svn/wat; git diff-tree --no-commit-id --name-only -r "$1" "$2" | while read -r line; do echo "Traitement du fichier $line ..."; if [ -f "$line" ]; then if expr match "$line" '\..*' || expr match "$line" '.*\.sh'; then echo "Fichier ignoré."; else echo "Envoi..."; echo $line; echo $(dirname "${line}"); mkdir -p $(dirname "${line}"); cp $line ./wat/$(dirname "${line}"); svn add wat/$line; echo "Fait."; fi; else echo "Suppression ..."; svn remove ./wat/$line; echo "Fait."; fi; done; cd ./wat; svn commit --username $3 --password $4 -m $2
